/**
 * Normalise a Copilot source body back into catalog prose.
 *
 * Reverses what the Copilot emit specs add around an artifact's body: the rule/agent H1 and the
 * rule's `<!-- Generated by sigil … -->` comment, a skill's leading `## When to Use` section and
 * `**Arguments:**` line, a prompt's `${input:name}` placeholders, and the Copilot body lexicon.
 *
 * Pure: no filesystem access.
 *
 * @module
 */
import { getTarget } from '../../targets';
import { reverseLexicon } from '../../targets/lexicon';
import type { ProviderLexicon } from '../../targets/lexicon';
import { fromCopilotPlaceholders } from '../../targets/prompt-args';
import type { PromptArg } from '../../targets/prompt-args';

/** The whole-file kinds this normaliser understands. */
export type CopilotBodyKind = 'rule' | 'agent' | 'skill' | 'prompt';

/** Result of normalising one source file's body. */
export interface NormalizedBody {
  body: string;
  title?: string;
  whenToUse?: string;
  argumentHint?: string;
  args?: PromptArg[];
  notes: string[];
}

const BOUNDARY_NOTE =
  'body keeps the generated ## Boundary section; set relatedArtifacts in the catalog file';
const CODING_GUIDELINES_NOTE =
  'body keeps the generated ## Coding guidelines to apply section; wire uses.rules with sigil patch';

/** A markdown ATX heading of any level, as the Copilot emitters write it. */
const HEADING_RE = /^#{1,6}\s/;
/** The rule/agent H1 the emitters write first: `# <title>`. */
const H1_RE = /^#\s+(.+)$/;
/** The rule's source comment, matching `<!-- Generated by sigil … -->`. */
const GENERATED_COMMENT_RE = /^<!-- Generated by sigil\b.*-->$/;
/** The skill's `**Arguments:** <hint>` line. */
const ARGUMENTS_RE = /^\*\*Arguments:\*\*\s*(.+)$/;
/** A fenced code block marker (``` or ~~~, up to three leading spaces). */
const FENCE_RE = /^\s{0,3}(`{3,}|~{3,})/;

/** The Copilot lexicon, read through the registry: only src/targets/ imports a provider folder. */
export function copilotLexicon(): ProviderLexicon {
  const { lexicon } = getTarget('copilot');
  if (!lexicon) throw new Error('The copilot target has no lexicon.');
  return lexicon;
}

/** Split into lines, normalising CRLF (and lone CR) to LF. */
function splitLines(text: string): string[] {
  return text.replace(/\r\n?/g, '\n').split('\n');
}

/** The line at `index`, or an empty string past the end (indexed access is `string | undefined`). */
function lineAt(lines: string[], index: number): string {
  return lines[index] ?? '';
}

function isBlank(line: string): boolean {
  return line.trim() === '';
}

function isFenceMarker(line: string): boolean {
  return FENCE_RE.test(line);
}

/** Drop leading and trailing blank lines, keeping internal blank lines (paragraph breaks). */
function trimBlankLines(lines: string[]): string {
  let start = 0;
  let end = lines.length;
  while (start < end && isBlank(lineAt(lines, start))) start++;
  while (end > start && isBlank(lineAt(lines, end - 1))) end--;
  return lines.slice(start, end).join('\n');
}

/** Index of the first non-blank line, or `lines.length` when there is none. */
function firstNonBlankIndex(lines: string[]): number {
  for (let i = 0; i < lines.length; i++) {
    if (!isBlank(lineAt(lines, i))) return i;
  }
  return lines.length;
}

/** The first non-blank line when it is the emitted H1, as `{ index, title }`. */
function firstH1Title(lines: string[]): { index: number; title: string } | undefined {
  const index = firstNonBlankIndex(lines);
  const match = H1_RE.exec(lineAt(lines, index));
  const title = match ? (match[1] ?? '').trim() : '';
  return title ? { index, title } : undefined;
}

/** Remove the rule's `<!-- Generated by sigil … -->` line, when it follows the removed H1. */
function removeGeneratedComment(lines: string[], from: number): void {
  let i = from;
  while (i < lines.length && isBlank(lineAt(lines, i))) i++;
  if (i < lines.length && GENERATED_COMMENT_RE.test(lineAt(lines, i))) lines.splice(i, 1);
}

/** End of a section: the next heading or `**Arguments:**` line, skipping fenced blocks. */
function nextSectionEnd(lines: string[], start: number): number {
  let inFence = false;
  for (let i = start; i < lines.length; i++) {
    const line = lineAt(lines, i);
    if (isFenceMarker(line)) {
      inFence = !inFence;
      continue;
    }
    if (inFence || isBlank(line)) continue;
    if (HEADING_RE.test(line) || ARGUMENTS_RE.test(line.trim())) return i;
  }
  return lines.length;
}

/** Extract the skill's leading `## When to Use` section (heading + content), removed in place. */
function extractWhenToUseAt(lines: string[], idx: number): string | undefined {
  if (lineAt(lines, idx).trim() !== '## When to Use') return undefined;
  const end = nextSectionEnd(lines, idx + 1);
  const text = trimBlankLines(lines.slice(idx + 1, end));
  lines.splice(idx, end - idx);
  return text === '' ? undefined : text;
}

/** Extract the skill's leading `**Arguments:** <hint>` line, when it is next. */
function extractArgumentHintAt(lines: string[], idx: number): string | undefined {
  const match = ARGUMENTS_RE.exec(lineAt(lines, idx).trim());
  if (!match) return undefined;
  const hint = (match[1] ?? '').trim();
  if (hint === '') return undefined;
  lines.splice(idx, 1);
  return hint;
}

/** Normalise a skill body: a leading `## Boundary` block stays; leading When to Use / Arguments come out. */
function normalizeSkillBody(lines: string[]): NormalizedBody {
  const result: NormalizedBody = { body: '', notes: [] };
  let idx = firstNonBlankIndex(lines);
  if (lineAt(lines, idx).trim() === '## Boundary') {
    idx = nextSectionEnd(lines, idx + 1);
  }
  const whenToUse = extractWhenToUseAt(lines, idx);
  if (whenToUse !== undefined) result.whenToUse = whenToUse;
  const argumentHint = extractArgumentHintAt(lines, idx);
  if (argumentHint !== undefined) result.argumentHint = argumentHint;
  result.body = trimBlankLines(lines);
  return result;
}

/** Normalise a prompt body: `${input:name}` placeholders back to `{{name}}`. */
function normalizePromptBody(lines: string[]): NormalizedBody {
  const { body, args } = fromCopilotPlaceholders(lines.join('\n'));
  const result: NormalizedBody = { body: trimBlankLines(splitLines(body)), notes: [] };
  if (args.length > 0) result.args = args;
  return result;
}

/** Normalise a rule/agent body: strip the emitted H1 and, for rules, the generated comment. */
function normalizeRuleOrAgentBody(kind: 'rule' | 'agent', lines: string[]): NormalizedBody {
  const result: NormalizedBody = { body: '', notes: [] };
  const h1 = firstH1Title(lines);
  if (h1 !== undefined) {
    result.title = h1.title;
    lines.splice(h1.index, 1);
    if (kind === 'rule') removeGeneratedComment(lines, h1.index);
  }
  result.body = trimBlankLines(lines);
  return result;
}

/** Apply the kind-specific body reversal, before the shared lexicon and note passes. */
function normalizeBodyByKind(kind: CopilotBodyKind, lines: string[]): NormalizedBody {
  if (kind === 'prompt') return normalizePromptBody(lines);
  if (kind === 'rule' || kind === 'agent') return normalizeRuleOrAgentBody(kind, lines);
  return normalizeSkillBody(lines);
}

/** Note a generated `## Boundary` / `## Coding guidelines to apply` section that stays in the body. */
function addRemainingHeadingNotes(result: NormalizedBody): void {
  let inFence = false;
  let hasBoundary = false;
  let hasCodingGuidelines = false;
  for (const line of result.body.split('\n')) {
    if (isFenceMarker(line)) {
      inFence = !inFence;
      continue;
    }
    if (inFence) continue;
    const trimmed = line.trim();
    if (trimmed === '## Boundary') hasBoundary = true;
    if (trimmed === '## Coding guidelines to apply') hasCodingGuidelines = true;
  }
  if (hasBoundary) result.notes.push(BOUNDARY_NOTE);
  if (hasCodingGuidelines) result.notes.push(CODING_GUIDELINES_NOTE);
}

/**
 * Reverse the Copilot emitters' additions to a body, returning catalog-shaped prose plus the
 * fields those additions carried (`title`, `whenToUse`, `argumentHint`, `args`).
 */
export function normalizeCopilotBody(kind: CopilotBodyKind, rawBody: string): NormalizedBody {
  const result = normalizeBodyByKind(kind, splitLines(rawBody));
  const lexicon = copilotLexicon();
  result.body = reverseLexicon(result.body, lexicon);
  if (result.whenToUse !== undefined) {
    result.whenToUse = reverseLexicon(result.whenToUse, lexicon);
  }
  addRemainingHeadingNotes(result);
  return result;
}
